
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_b3pw91_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_b3pw91", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.524856880857115e+00, -3.458379604747346e+00, -3.365261827987048e+00, -3.236340153791745e+00, -3.060815703158799e+00, -2.827520402828051e+00, -2.527912128380033e+00, -2.161459673102130e+00, -1.742840488493906e+00, -1.305706974305243e+00, -8.882961446763494e-01, -6.097608644800678e-01, -5.305092924519232e-01, -4.373790169755727e-01, -3.165953837469404e-01, -2.028233303827691e-01, -1.224551494052803e-01, -7.292273248931842e-02, -4.484704724755420e-02, -3.015454996806087e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


